'use strict';
// Reports display only fields supplied by the company API; missing series are omitted.
function renderCompanyReport(company) {
  const sources = Array.isArray(company.sources) ? company.sources : [];
  const history = Array.isArray(company.hiringHistory) ? company.hiringHistory.filter(point => Number.isFinite(point.count) && point.count >= 0) : [];
  const max = Math.max(1, ...history.map(point => point.count));
  const roleGroups = Array.isArray(company.hiringRoles) ? company.hiringRoles : [];
  const salaryReports = Array.isArray(company.reportedSalaries) ? company.reportedSalaries : [];
  $('#company-page').innerHTML = `<a class="back" href="#jobs">← Back to search</a><div class="section-heading"><h1>${escapeHTML(company.name)}</h1><span class="eyebrow">Hiring report</span></div><div class="detail-actions report-subtitle">${companyMark(company)}${capable('follows') ? `<button class="button outline" data-follow="${escapeHTML(company.id)}" aria-pressed="${company.followed === true}">${company.followed ? 'Following ✓' : 'Follow +'}</button>` : ''}</div>${company.description ? `<p class="detail-description">${escapeHTML(company.description)}</p>` : ''}<div class="report-facts">${company.monitoringSince ? `<p>Monitoring since <time>${escapeHTML(dateText(company.monitoringSince))}</time></p>` : ''}<p>${escapeHTML(company.coverage?.description || company.statusLabel || 'Coverage details unavailable.')}</p></div>${history.length ? `<section aria-label="Historical hiring"><h2>Hiring over time.</h2><div class="hiring-history">${history.map(point => `<div><span class="history-bar" style="--height:${Math.max(2, point.count / max * 100)}%"></span><b>${point.count}</b><small>${escapeHTML(dateText(point.date))}</small></div>`).join('')}</div></section>` : '<p class="helper">Historical hiring data is not available for this company.</p>'}${roleGroups.length ? `<section><h2>Hiring roles.</h2><ul>${roleGroups.map(role => `<li>${escapeHTML(role.name)}${Number.isFinite(role.count) ? ` · ${role.count}` : ''}</li>`).join('')}</ul></section>` : ''}${salaryReports.length ? `<section><h2>Reported salaries.</h2><ul>${salaryReports.map(item => `<li>${escapeHTML(item.role || '')} ${escapeHTML(item.text || '')}</li>`).join('')}</ul></section>` : ''}<section class="tracked-sources"><h2>At the source.</h2><p>${company.lastSuccessfulCheckAt ? `Last successful check ${escapeHTML(dateText(company.lastSuccessfulCheckAt))}` : 'No successful check reported.'}</p>${sources.length ? `<ul>${sources.map(source => { const url = sourceURL(source.url); return url ? `<li><a href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(source.label || new URL(url).hostname)} ↗</a>${source.lastSuccessfulCheckAt ? ` · ${escapeHTML(dateText(source.lastSuccessfulCheckAt))}` : ''}</li>` : ''; }).join('')}</ul>` : '<p>No tracked career pages reported.</p>'}</section>`;
}
